237	    var areaEl = document.getElementById("header-cash-area");
238	    if (areaEl) {
239	      areaEl.className = "header-stat";
240	      areaEl.style.cssText = "cursor: default; min-width: 100px;";
241	    }
242	
243	    var fundCarouselData = fundItems.map(function (f) {
244	      return { label: f.label, value: f.value, color: f.color };
245	    });
246	
247	    if (!window._fundsCarouselTimer) {
248	      // 首次启动
249	      window._fundsCarouselIdx = 0;
